const DIGITOS_VISIBLES = 3;   // cola visible del telefono. 0 = maximo anonimato.

// ---------- Redaccion determinista de PII (correos + telefonos) ----------
function enmascararCorreos(txt) {
  if (!txt) return txt;
  // conserva hasta 3 chars del local + dominio; enmascara el resto
  return String(txt).replace(
    /([A-Za-z0-9._%+-]{1,3})[A-Za-z0-9._%+-]*(@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g,
    '$1***$2'
  );
}
function enmascararTelefonos(txt) {
  if (!txt) return txt;
  // +503 opcional + numero SV de 8 digitos (empieza 2/6/7), separadores opcionales
  const re = /(\+503[\s-]?)?([267](?:[\s-]?\d){7})/g;
  return String(txt).replace(re, (m, pais, cuerpo) => {
    const d = cuerpo.replace(/\D/g, '');
    if (d.length !== 8) return m;                 // no es telefono SV -> intacto
    const vis = DIGITOS_VISIBLES > 0 ? d.slice(-DIGITOS_VISIBLES) : '';
    const oc  = '*'.repeat(8 - (DIGITOS_VISIBLES > 0 ? DIGITOS_VISIBLES : 0));
    const mascara = oc.slice(0, 4) + '-' + oc.slice(4) + vis;  // ****-*123
    return (pais ? '+503 ' : '') + mascara;
  });
}
function redactarPII(txt) {
  // correos PRIMERO (para no romper emails con digitos), luego telefonos
  return enmascararTelefonos(enmascararCorreos(txt || ''));
}

// ---------- Enmascarado de correo estilo slots (kev***@dominio) ----------
function maskEmailSlot(correo) {
  if (!correo || typeof correo !== 'string' || correo.indexOf('@') === -1) return null;
  const [local, dominio] = correo.split('@');
  return local.slice(0, 3) + '***@' + dominio;
}

// ---------- Parseo del JSON del extractor (con red de seguridad) ----------
let datos = {};
try {
  let raw = String($json.text || '').trim();
  raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();  // limpia fences
  datos = JSON.parse(raw);
} catch (e) {
  datos = { nombre: null, correo: null, correo_valido: false,
            validacion: 'sin_extraccion', resumen: 'Extractor no disponible este turno' };
}

// ---------- Validacion determinista del correo (autoridad final) ----------
const correoCliente = datos.correo || null;
const REGEX_CORREO = /^[^\s@,]+@[^\s@,]+\.[^\s@,]{2,}$/;
let correo_valido = false;
let validacion = datos.validacion || 'ok';
if (correoCliente) {
  correo_valido = REGEX_CORREO.test(String(correoCliente).trim());
  validacion = correo_valido ? 'correo_valido' : 'correo_invalido';
} else if (!datos.validacion) {
  validacion = 'sin_correo';
}

// ---------- slots_snapshot con correo enmascarado ----------
const slots_snapshot = {
  nombre: datos.nombre || null,
  correo: correo_valido ? maskEmailSlot(correoCliente) : null,
};

// ---------- Redaccion de la conversacion para el log auditable ----------
const input_redactado  = redactarPII($json.input_raw);
const output_redactado = redactarPII($json.output_raw);

return [{
  json: {
    validacion,
    correo_valido,                              // boolean -> el If usa "is true" (Convert types ON)
    nombre: datos.nombre || null,
    correo_mask: slots_snapshot.correo,
    resumen: datos.resumen || null,
    slots_snapshot: JSON.stringify(slots_snapshot),
    input_redactado,
    output_redactado,
  }
}];
